#include <madron/timbre/GrainResynthesizer.h>

#include <algorithm>
#include <cmath>
#include <numbers>

namespace madron::timbre {
bool GrainResynthesizer::prepare(const double sampleRate){if(sampleRate<=0.0)return false;sampleRate_=sampleRate;inputRing_.assign(16384,0.0f);ola_.assign(32768,0.0f);norm_.assign(32768,0.0f);reset();return true;}
void GrainResynthesizer::reset() noexcept {std::fill(inputRing_.begin(),inputRing_.end(),0.0f);std::fill(ola_.begin(),ola_.end(),0.0f);std::fill(norm_.begin(),norm_.end(),0.0f);voices_.fill({});inputWrite_=outputTime_=0;}
void GrainResynthesizer::applyEvent(const PartialEvent& event) noexcept {Voice* voice=nullptr;for(auto& candidate:voices_)if(candidate.active&&candidate.trackId==event.trackId){voice=&candidate;break;}if(voice==nullptr&&event.type!=PartialEventType::Stop){for(auto& candidate:voices_)if(!candidate.active){voice=&candidate;break;}if(voice==nullptr)voice=&*std::min_element(voices_.begin(),voices_.end(),[](const Voice&a,const Voice&b){return a.smoothAmplitude<b.smoothAmplitude;});voice->trackId=event.trackId;voice->samplesToMark=0.0f;}if(voice==nullptr)return;if(event.type==PartialEventType::Stop){voice->active=false;return;}voice->active=true;voice->frequency=std::clamp(event.frequencyHz,20.0f,8000.0f);voice->amplitude=std::clamp(event.amplitude,0.0f,1.0f);}
float GrainResynthesizer::processSample(const float raw,const GrainParameters& p) noexcept {const std::size_t out=outputTime_%ola_.size();const float y=norm_[out]>1.0e-9f?ola_[out]/norm_[out]:0.0f;ola_[out]=norm_[out]=0.0f;inputRing_[inputWrite_]=std::isfinite(raw)?raw:0.0f;inputWrite_=(inputWrite_+1)%inputRing_.size();++outputTime_;const std::size_t voices=std::clamp<std::size_t>(p.activeVoices,1,maximumVoices);for(std::size_t i=0;i<voices;++i){auto& voice=voices_[i];if(!voice.active)continue;voice.smoothAmplitude+=0.02f*(voice.amplitude-voice.smoothAmplitude);voice.samplesToMark-=1.0f;if(voice.samplesToMark<=0.0f)scheduleGrain(voice,p);}return std::isfinite(y)?y:0.0f;}
void GrainResynthesizer::scheduleGrain(Voice& voice,const GrainParameters& p) noexcept {const float ratio=std::exp2(std::clamp(p.transposeCents,-2400.0f,2400.0f)/1200.0f);const float formant=std::exp2(std::clamp(p.formantCents,-2400.0f,2400.0f)/1200.0f);const float sourcePeriod=std::clamp(static_cast<float>(sampleRate_)/std::max(20.0f,voice.frequency),4.0f,512.0f);const float target=std::clamp(p.targetFrequencyHz>0.0f?p.targetFrequencyHz:voice.frequency*ratio,20.0f,12000.0f);voice.samplesToMark+=std::max(4.0f,static_cast<float>(sampleRate_)/target);const std::size_t length=std::clamp<std::size_t>(static_cast<std::size_t>(std::lround(sourcePeriod*2.0f)),16,1024);const float center=static_cast<float>(inputWrite_)-sourcePeriod;const float half=0.5f*static_cast<float>(length);const float gain=std::max(0.02f,voice.smoothAmplitude);for(std::size_t i=0;i<length;++i){const float w=0.5f-0.5f*std::cos(2.0f*std::numbers::pi_v<float>*static_cast<float>(i)/static_cast<float>(length));const float sample=cubicRead(center+(static_cast<float>(i)-half)*formant);const std::size_t pos=(outputTime_+latencySamples+i)%ola_.size();ola_[pos]+=sample*w*gain;norm_[pos]+=w*gain;}}
float GrainResynthesizer::cubicRead(float position) const noexcept {const int size=static_cast<int>(inputRing_.size());auto wrap=[size](int x){x%=size;return x<0?x+size:x;};const int base=static_cast<int>(std::floor(position));const float f=position-std::floor(position);const float y0=inputRing_[wrap(base-1)],y1=inputRing_[wrap(base)],y2=inputRing_[wrap(base+1)],y3=inputRing_[wrap(base+2)];const float a0=y3-y2-y0+y1,a1=y0-y1-a0,a2=y2-y0;return ((a0*f+a1)*f+a2)*f+y1;}
} // namespace madron::timbre
